import { FieldTypes } from '@zn-apps/ui-data-core'

/**
 * Create/edit form for one external status. The id is generated by the store,
 * so the user only provides the labels; English is required and Spanish falls
 * back to it when empty.
 */
export function externalStatusFormSchema({ t, errors = {} }) {
  return {
    variant: 'outlined',
    sections: [
      {
        layout: 1,
        fields: [
          {
            path: 'labels.en',
            type: FieldTypes.TEXT,
            label: t('settings.externalStatusLabelEn'),
            required: true,
            error: errors.labelEn,
            maxlength: 60
          },
          {
            path: 'labels.es',
            type: FieldTypes.TEXT,
            label: t('settings.externalStatusLabelEs'),
            hint: t('settings.externalStatusLabelEsHint'),
            maxlength: 60
          }
        ]
      }
    ]
  }
}
